EXPECTED_SHA256 = {'config.py': '6442c927dd3edd93b15bd4348075d0a2cd304100f6bc9fa4dfaa3b318f71536e', 'rollback.py': '6734e021fcd9765626c0c1c95b1b280aecd110fb94e2127ff9c46104da597df0', 'network_test.py': '2d3192a713ea1d061f4abdbc6c95dc72ae1e7623a13d717d40861d7ff5085fbc', 'test_cpu.py': '1476bdefb7cf38c6eae5129550f306f602072e123020b637189d8d5711835d14', 'network.py': '33548f1094f6b16ea5f42890e59b8830e603b514d5e877eaba08398cc6343406', 'ui.py': '7a4028151029013b66ad37ed1ef9ac7092984b4b5a93f07e46e5b2c54ca39ad1', 'cpu.py': '560c606d877c68ce3a6ff88f7b8db531fc53e90e207e3519762e9e87f85561c1', 'main.py': '87c3adb4a32b2b676191ff8cf0627d26c8252237c2730db6247453ba4b544083', 'BUILD.txt': '0f17c2de65dd41208bdc631adc2a49e110756aaf14e69430d7c6cfd1e93b626d', 'V30_CHECK.txt': '23a2f6574b2d586843448ff594887f87f77b4fece2483433e00aca78540fb775'}

required = ["main.py", "config.py", "ui.py", "network.py", "rollback.py", "cpu.py"]
missing = [name for name in required if not (ROOT / name).exists()]

if missing:
    print()
    print("ERROR: Put this installer in the SAME folder as main.py.")
    print("Missing:", ", ".join(missing))
    print()
    input("Press Enter to close...")
    raise SystemExit(1)

print()
print("Installing Tennis for Two v30 FULL...")
print("This installer does NOT require v28 or v29 first.")
print()

# Back up every file this installer replaces.
for name in PAYLOAD:
    path = ROOT / name
    if path.exists():
        backup = ROOT / (name + ".before_v30_full")
        if not backup.exists():
            shutil.copy2(path, backup)

# Decode and write the complete known-good v30 file set.
for name, encoded in PAYLOAD.items():
    raw = zlib.decompress(base64.b64decode(encoded))
    actual = hashlib.sha256(raw).hexdigest()
    expected = EXPECTED_SHA256[name]
    if actual != expected:
        raise RuntimeError(f"Internal installer checksum failed for {name}")
    (ROOT / name).write_bytes(raw)

# Syntax-check all installed Python files before reporting success.
for name in (
    "config.py", "rollback.py", "network_test.py", "test_cpu.py",
    "network.py", "ui.py", "cpu.py", "main.py",
):
    source = (ROOT / name).read_text(encoding="utf-8")
    compile(source, str(ROOT / name), "exec")

# Verify the settings that were accidentally left old in the earlier installer.
import re
config_text = (ROOT / "config.py").read_text(encoding="utf-8")
checks = {
    "FPS=120": bool(re.search(r"(?m)^FPS\s*=\s*120\s*$", config_text)),
    "BUFFER=60": bool(re.search(r"(?m)^ONLINE_INPUT_DELAY\s*=\s*60\s*$", config_text)),
    "PROTOCOL=29": bool(re.search(r"(?m)^PROTOCOL_VERSION\s*=\s*29\s*$", config_text)),
}
if not all(checks.values()):
    raise RuntimeError("v30 verification failed: " + repr(checks))

